SELECT sku, gtin, name, pack_size, case_units, selling_price_inr, cost_inr, flow
FROM store.products
WHERE name ILIKE '%atta%' AND pack_size ILIKE '%5 kg%';

SELECT sku, gtin, name, pack, case_units, price_inr, cost_inr, flow
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5 kg%';

SELECT SUM(units_sold) as total_units_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';
